    function getIndianCurrency(float $number, string $words_val)
        {
            $decimal = round($number - ($no = floor($number)) , 2) * 100;
            $hundred = null;
            $digits_length = strlen($no);
            $i = 0;
            $str = array();
            $words = array(
                0 => '',
                1 => 'One',
                2 => 'Two',
                3 => 'Three',
                4 => 'Four',
                5 => 'Five',
                6 => 'Six',
                7 => 'Seven',
                8 => 'Eight',
                9 => 'Nine',
                10 => 'Ten',
                11 => 'Eleven',
                12 => 'Twelve',
                13 => 'Thirteen',
                14 => 'Fourteen',
                15 => 'Fifteen',
                16 => 'Sixteen',
                17 => 'Seventeen',
                18 => 'Eighteen',
                19 => 'Nineteen',
                20 => 'Twenty',
                30 => 'Thirty',
                40 => 'Forty',
                50 => 'Fifty',
                60 => 'Sixty',
                70 => 'Seventy',
                80 => 'Eighty',
                90 => 'Ninety'
            );
            $digits = array(
                '',
                'Hundred',
                'Thousand',
                'Lakh',
                'Crore'
            );
            while ($i < $digits_length)
            {
                $divider = ($i == 2) ? 10 : 100;
                $number = floor($no % $divider);
                $no = floor($no / $divider);
                $i += $divider == 10 ? 1 : 2;
                if ($number)
                {
                    $plural = (($counter = count($str)) && $number > 9) ? 's' : null;
                    $hundred = ($counter == 1 && $str[0]) ? ' and ' : null;
                    $str[] = ($number < 21) ? $words[$number] . ' ' . $digits[$counter] . $plural . ' ' . $hundred : $words[floor($number / 10) * 10] . ' ' . $words[$number % 10] . ' ' . $digits[$counter] . $plural . ' ' . $hundred;
                }
                else $str[] = null;
            }
            $Rupees = implode('', array_reverse($str));
            $paise = ($decimal > 0) ? "." . ($words[$decimal / 10] . " " . $words[$decimal % 10]) . ' Paise' : '';
            return ($Rupees ? $Rupees . '' . $words_val : '') . $paise . ' Only';
            //return ($Rupees ? $Rupees . 'Rupees ' : '') . $paise .'Only';
            
        }


    function getGrdeValue($grade , $conn){
        
                if ($grade == 'NA') {
                    $grd = [0]; // Default value as an array containing 0
                } else {
                    $grd = $grade;
                }
                
                // Ensure $grd is properly formatted as a comma-separated list
                if (!is_array($grd)) {
                    $grd = explode(',', $grd); // Convert to an array if it is a string
                }
                
                // Validate $grd to contain only integers
                $grd = array_filter($grd, function($value) {
                    return is_numeric($value) && intval($value) > 0; // Allow only positive integers
                });
                
                // Convert back to a comma-separated string for SQL
                $grdList = implode(',', $grd);
                
                if (!empty($grdList)) {
                    // Only execute the query if $grdList is not empty
                    $q = "SELECT GROUP_CONCAT(grade) as gradeName FROM grade WHERE id IN ($grdList)";
                // echo $q; // Debugging: Display the query
                    
                    $resQ = $conn->query($q);
                    if ($resQ) {
                        $prodLatest = $resQ->fetch_assoc();
                        $gradeName = $prodLatest['gradeName'];
                    } else {
                        // Handle SQL query errors
                        echo "SQL Error: " . $conn->error;
                    }
                } else {
                    // Handle case where $grdList is empty
                    $gradeName = "NA"; // Set a default value or handle it appropriately
                //  echo "No valid grades to fetch.";
                }     
                
                
                return $gradeName;
                
                
    }

    require_once __DIR__.'/retest_helpers.php';

    function medicap_send_retest_intimation($conn, $input, $plantId, $empId, $entryDate) {
        $required = array('material_code', 'grn_no', 'batch_no', 'retest_date');
        foreach ($required as $field) {
            if (!isset($input[$field]) || trim((string)$input[$field]) === '') {
                return array('status' => 'failed', 'msg' => 'Missing field: '.$field);
            }
        }
        $grn = $conn->real_escape_string((string)$input['grn_no']);
        $code = $conn->real_escape_string((string)$input['material_code']);
        $batch = $conn->real_escape_string((string)$input['batch_no']);
        $retestDate = $conn->real_escape_string((string)$input['retest_date']);
        $plantEsc = $conn->real_escape_string((string)$plantId);
        $check = $conn->query("SELECT id, status FROM retest WHERE plant_id='".$plantEsc."' AND grn_no='".$grn."' AND material_code='".$code."' AND batch_no='".$batch."' AND retest_date='".$retestDate."' ORDER BY id DESC LIMIT 1");
        if ($check && $check->num_rows > 0) {
            $existing = $check->fetch_assoc();
            $st = strtolower(trim((string)($existing['status'] ?? '')));
            if (in_array($st, array('intimated', 'pending', 'sampled', 'requested'), true)) {
                return array('status' => 'success', 'msg' => 'Intimation already sent to QC.', 'retest_id' => $existing['id'], 'intimation_status' => 'Sent to QC');
            }
            $conn->query("UPDATE retest SET status='intimated', entry_by='".$conn->real_escape_string((string)$empId)."', entry_date='".$entryDate."' WHERE id='".$existing['id']."'");
            return array('status' => 'success', 'msg' => 'Intimation sent to QC.', 'retest_id' => $existing['id'], 'intimation_status' => 'Sent to QC');
        }
        $arNo = $conn->real_escape_string((string)($input['ar_no'] ?? ''));
        $releaseDate = $conn->real_escape_string((string)($input['release_date'] ?? ''));
        $qty = $conn->real_escape_string((string)($input['qty'] ?? ''));
        $unit = $conn->real_escape_string((string)($input['unit'] ?? ''));
        $mfgDate = $conn->real_escape_string((string)($input['mfg_date'] ?? ''));
        $expDate = $conn->real_escape_string((string)($input['exp_date'] ?? ''));
        $sql = "INSERT INTO retest (plant_id, material_code, batch_no, grn_no, ar_no, release_date, retest_date, qty, unit, mfg_date, exp_date, status, entry_by, entry_date)
                VALUES ('".$plantEsc."', '".$code."', '".$batch."', '".$grn."', '".$arNo."', '".$releaseDate."', '".$retestDate."', '".$qty."', '".$unit."', '".$mfgDate."', '".$expDate."', 'intimated', '".$conn->real_escape_string((string)$empId)."', '".$entryDate."')";
        if ($conn->query($sql)) {
            return array('status' => 'success', 'msg' => 'Intimation sent to QC.', 'retest_id' => $conn->insert_id, 'intimation_status' => 'Sent to QC');
        }
        return array('status' => 'failed', 'msg' => $conn->error);
    }

    function ensureDamageImageColumns($conn) {
        $columns = array(
            'damaeImg1' => "VARCHAR(255) NULL DEFAULT 'NA'",
            'damaeImg2' => "VARCHAR(255) NULL DEFAULT 'NA'",
        );
        foreach ($columns as $name => $definition) {
            $check = $conn->query("SHOW COLUMNS FROM challan_materials LIKE '".$conn->real_escape_string($name)."'");
            if ($check && $check->num_rows === 0) {
                $conn->query("ALTER TABLE challan_materials ADD `".$name."` ".$definition);
            }
        }
    }

    function resolveDamageImageValue($row, $imgKey) {
        $imgVal = trim((string)($row[$imgKey] ?? $row[strtolower($imgKey)] ?? ''));
        if ($imgVal === '' || strtoupper($imgVal) === 'NA') {
            $details = $row['receiving_details'] ?? array();
            if (is_object($details)) {
                $details = (array) $details;
            }
            if (is_array($details)) {
                $imgVal = trim((string)($details[$imgKey] ?? $details[strtolower($imgKey)] ?? ''));
            }
        }
        if ($imgVal === '' || strtoupper($imgVal) === 'NA') {
            return 'NA';
        }
        return $imgVal;
    }

    function getDamageUploadDir() {
        $dir = dirname(__DIR__) . '/upload/damage/';
        if (!is_dir($dir)) {
            mkdir($dir, 0777, true);
        }
        return $dir;
    }

    function saveDamageUploadFile($fieldName, $str, $suffix) {
        if (empty($_FILES[$fieldName]['name']) || !isset($_FILES[$fieldName]['error']) || $_FILES[$fieldName]['error'] !== UPLOAD_ERR_OK) {
            return 'NA';
        }
        $file_tmp = $_FILES[$fieldName]['tmp_name'];
        $file_name = $_FILES[$fieldName]['name'];
        if (empty($file_tmp) || !is_uploaded_file($file_tmp)) {
            return 'NA';
        }
        $file_ext = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));
        if ($file_ext === '') {
            return 'NA';
        }
        $filename = $str . $suffix . '.' . $file_ext;
        if (move_uploaded_file($file_tmp, getDamageUploadDir() . $filename)) {
            return $filename;
        }
        return 'NA';
    }

    function getNextArNoBase($conn, $plantId)
    {
        $maxNum = 0;
        $tables = array('stock_book', 'sampling_batches');
        foreach ($tables as $tbl) {
            $sql = "SELECT ar_no FROM ".$tbl." WHERE plant_id = '".$plantId."' AND ar_no LIKE 'AR%'";
            $res = $conn->query($sql);
            if ($res) {
                while ($row = $res->fetch_assoc()) {
                    $num = intval(preg_replace('/[^0-9]/', '', $row['ar_no']));
                    if ($num > $maxNum) {
                        $maxNum = $num;
                    }
                }
            }
        }
        return $maxNum;
    }

    function generateReceivingGrnNo($cmId, $materialType)
    {
        $year = date('y');
        $matType = 'PM';
        if ($materialType === 'Raw Material') {
            $matType = 'RM';
        }
        return $matType.$year.str_pad(intval($cmId), 5, '0', STR_PAD_LEFT);
    }

    function createGrnArForReceivingApproval($conn, $cmId, $plantId, $empId, $entryDate)
    {
        $cmId = intval($cmId);
        if ($cmId <= 0) {
            return array('grn_no' => '', 'ar_nos' => array(), 'batches_updated' => 0);
        }

        $cmSql = "SELECT c.*, c1.inward_no, c1.vendor_no, c1.ch_no, m.material_type, m.Artwork_Order_No, m.Artwork_Version_No
                FROM challan_materials c
                LEFT JOIN challan c1 ON c.challan_no = c1.challan_no
                LEFT JOIN material m ON c.material_code = m.material_code
                WHERE c.id = '".$cmId."' LIMIT 1";
        $cmRes = $conn->query($cmSql);
        if (!$cmRes || $cmRes->num_rows == 0) {
            return array('grn_no' => '', 'ar_nos' => array(), 'batches_updated' => 0);
        }
        $cm = $cmRes->fetch_assoc();

        $grn_no = trim($cm['grn_no'] ?? '');
        if ($grn_no === '') {
            $grn_no = generateReceivingGrnNo($cmId, $cm['material_type'] ?? '');
        }

        $conn->query("UPDATE challan_materials SET grn_no = '".$grn_no."', grn_date = '".$entryDate."', grn_by = '".$empId."',
            grn = 'Approved', status = 'Approved' WHERE id = '".$cmId."'");

        $batchSql = "SELECT s.id as batchId, s.batch_no, s.challan_no, s.qty_received, s.pack_size, s.unit, s.total_containers,
            s.mfg_date, s.exp_date, s.material_code, s.trackingId, s.clientGrpCode, s.clientSubGrpCode, s.tax_invoice, s.ar_no, s.status,
            c.inward_date, c.vendor_no, c.rate, c.receiving_no, c.grn_date
            FROM sampling_batches s
            LEFT JOIN challan_materials c ON c.material_code = s.material_code AND c.challan_no = s.challan_no AND c.id = '".$cmId."'
            WHERE s.material_code = '".$cm['material_code']."' AND s.challan_no = '".$cm['challan_no']."'
            AND (s.plant_id = '".$plantId."' OR IFNULL(s.plant_id,'') = '')";

        $batchRes = $conn->query($batchSql);
        if (!$batchRes || $batchRes->num_rows == 0) {
            $batchNo = trim($cm['batch_no'] ?? '');
            if ($batchNo !== '') {
                $conn->query("INSERT INTO sampling_batches (plant_id, material_code, batch_no, challan_no, ch_no, qty_received, total_containers, unit, status, isGrnReceive)
                    VALUES ('".$plantId."', '".$cm['material_code']."', '".$batchNo."', '".$cm['challan_no']."', '".($cm['ch_no'] ?? '')."',
                    '".($cm['received_qty'] ?? '0')."', '".($cm['containers'] ?? '0')."', '".($cm['unit'] ?? '')."', 'Pending', 'NO')");
                $batchRes = $conn->query($batchSql);
            }
        }
        if (!$batchRes || $batchRes->num_rows == 0) {
            return array('grn_no' => $grn_no, 'ar_nos' => array(), 'batches_updated' => 0);
        }

        $arSeq = getNextArNoBase($conn, $plantId);
        $arNos = array();
        $batchesUpdated = 0;

        while ($batch = $batchRes->fetch_assoc()) {
            $ar_no = trim($batch['ar_no'] ?? '');
            if ($ar_no === '') {
                $arSeq++;
                $ar_no = 'AR'.$arSeq;
            }

            $conn->query("UPDATE sampling_batches SET grn_no = '".$grn_no."', ar_no = '".$ar_no."', status = 'Approved', isGrnReceive = 'NO', plant_id = '".$plantId."' WHERE id = '".$batch['batchId']."'");
            $arNos[] = $ar_no;
            $batchesUpdated++;

            $existsSql = "SELECT id FROM stock_book WHERE plant_id = '".$plantId."' AND material_code = '".$batch['material_code']."'
                AND batch_no = '".$batch['batch_no']."' AND grn_no = '".$grn_no."' LIMIT 1";
            $existsRes = $conn->query($existsSql);
            if ($existsRes && $existsRes->num_rows > 0) {
                continue;
            }

            $vendor_no = $batch['vendor_no'] ? $batch['vendor_no'] : ($cm['vendor_no'] ?? '');
            $rate = $batch['rate'] ? $batch['rate'] : ($cm['rate'] ?? '0');
            $inward_date = $batch['inward_date'] ? $batch['inward_date'] : $entryDate;
            $artwork_no = $cm['Artwork_Order_No'] ? $cm['Artwork_Order_No'] : 'NA';
            $version_no = $cm['Artwork_Version_No'] ? $cm['Artwork_Version_No'] : 'NA';

            $sqlStock = "INSERT INTO stock_book (`plant_id`,`trackingId`, `inword_no`, `inword_date`, `grn_no`, `ar_no`, `batch_no`, `stock_type`, `manufacturer_no`, `vendor_no`,`material_code`, `qty`, `lod_per`, `unit`, `rate`, `rate_per`,
                `mfg_date`, `exp_date`, `containers`, `total_containers`, `receiving_no`, `grn_date`, `pack_size`, `entry_by`, `entry_date`, `artwork_no`, `version_no`,`clientGrpCode`,`clientSubGrpCode`,`tax_invoice`) VALUES ('".$plantId."',
                '".$batch['trackingId']."','".$cm['inward_no']."', '".$inward_date."', '".$grn_no."','".$ar_no."', '".$batch['batch_no']."', 'NORMAL', '".$vendor_no."', '".$vendor_no."', '".$batch['material_code']."',
                '".$batch['qty_received']."', '".$batch['unit']."','".$batch['unit']."', '".$rate."', '".$batch['unit']."', '".$batch['mfg_date']."','".$batch['exp_date']."', '".$batch['total_containers']."', '".$batch['total_containers']."', '".$batch['receiving_no']."',
                '".$entryDate."', '".$batch['pack_size']."', '".$empId."', '".$entryDate."', '".$artwork_no."' ,'".$version_no."' ,'".$batch['clientGrpCode']."' ,'".$batch['clientSubGrpCode']."' ,'".$batch['tax_invoice']."')";
            $conn->query($sqlStock);
        }

        return array('grn_no' => $grn_no, 'ar_nos' => $arNos, 'batches_updated' => $batchesUpdated);
    }

    function saveReceivingChecklistTransaction($conn, $recNo, $plantId, $checklistItems)
    {
        $recNoEsc = $conn->real_escape_string($recNo);
        $plantIdEsc = $conn->real_escape_string($plantId ?? '');
        $conn->query("DELETE FROM checklist_transaction WHERE trans_id = '".$recNoEsc."' AND correction = 'ReceivingChecklist'");

        if (!is_array($checklistItems) || count($checklistItems) === 0) {
            return 0;
        }

        $savedCount = 0;
        foreach ($checklistItems as $chkListData) {
            if (empty($chkListData['id']) || !is_numeric($chkListData['id'])) {
                continue;
            }

            $chkId = intval($chkListData['id']);
            $module = $conn->real_escape_string($chkListData['module'] ?? 'Receiving');
            $formName = $conn->real_escape_string($chkListData['form_name'] ?? 'Receiving');
            $department = $conn->real_escape_string($chkListData['department'] ?? 'Store');
            $params = $conn->real_escape_string($chkListData['check_point'] ?? '');
            $chkType = $conn->real_escape_string($chkListData['evl_pr'] ?? '');
            $chkValue = $conn->real_escape_string($chkListData['check'] ?? '');

            $chkSql = "INSERT INTO checklist_transaction(trans_id, chk_id, plant_id, module, form, deprt, params, chk_type, chk_value, correction)
                    VALUES ('".$recNoEsc."', '".$chkId."', '".$plantIdEsc."', '".$module."', '".$formName."', '".$department."', '".$params."', '".$chkType."', '".$chkValue."', 'ReceivingChecklist')";

            if ($conn->query($chkSql)) {
                $savedCount++;
            }
        }

        return $savedCount;
    }

    function fetchReceivingChecklistRows($conn, $recNo, $receivingDetailsJson = null)
    {
        $output = array();
        $recNoEsc = $conn->real_escape_string(trim((string)$recNo));
        if ($recNoEsc !== '') {
            $sql = "SELECT ct.*, mc.heading, d.check_point AS master_check_point
                    FROM checklist_transaction ct
                    LEFT JOIN mst_chlist_dtl d ON CAST(ct.chk_id AS UNSIGNED) = d.id
                    LEFT JOIN master_checklist mc ON d.chklist_id = mc.id
                    WHERE ct.trans_id = '".$recNoEsc."'
                    AND ct.correction = 'ReceivingChecklist'
                    ORDER BY mc.id ASC, d.id ASC";
            $result = $conn->query($sql);
            if ($result && $result->num_rows > 0) {
                while ($row = $result->fetch_assoc()) {
                    if (empty($row['params']) && !empty($row['master_check_point'])) {
                        $row['params'] = $row['master_check_point'];
                    }
                    $output[] = $row;
                }
                return $output;
            }
        }

        $details = is_string($receivingDetailsJson) ? json_decode($receivingDetailsJson, true) : $receivingDetailsJson;
        if (!is_array($details) || empty($details['checklist_answers']) || !is_array($details['checklist_answers'])) {
            return $output;
        }

        foreach ($details['checklist_answers'] as $answer) {
            if (!is_array($answer)) {
                continue;
            }
            $output[] = array(
                'trans_id' => $recNo,
                'chk_id' => $answer['id'] ?? '',
                'module' => $answer['module'] ?? 'Receiving',
                'form' => $answer['form_name'] ?? 'Receiving',
                'deprt' => $answer['department'] ?? 'Store',
                'params' => $answer['check_point'] ?? '',
                'master_check_point' => $answer['check_point'] ?? '',
                'chk_type' => $answer['evl_pr'] ?? '',
                'chk_value' => $answer['check'] ?? '',
                'heading' => $answer['heading'] ?? 'Receiving Checklist',
            );
        }

        return $output;
    }

    function normalizeStoredDamageChecklistItems($items, $recNo = '')
    {
        $output = array();
        if (!is_array($items)) {
            return $output;
        }
        foreach ($items as $answer) {
            if (!is_array($answer)) {
                continue;
            }
            $checkPoint = $answer['check_point'] ?? $answer['params'] ?? '';
            if (trim((string)$checkPoint) === '') {
                continue;
            }
            $output[] = array(
                'trans_id' => $recNo,
                'chk_id' => $answer['id'] ?? '',
                'module' => $answer['module'] ?? 'Receiving',
                'form' => $answer['form_name'] ?? $answer['form'] ?? 'Damage',
                'deprt' => $answer['department'] ?? $answer['deprt'] ?? 'Store',
                'params' => $checkPoint,
                'master_check_point' => $checkPoint,
                'chk_type' => $answer['evl_pr'] ?? $answer['chk_type'] ?? '',
                'chk_value' => $answer['check'] ?? $answer['chk_value'] ?? '',
                'heading' => $answer['heading'] ?? 'Damage Container Checklist',
            );
        }
        return $output;
    }

    function fetchReceivingDamageChecklistRows($conn, $recNo, $receivingDetailsJson = null, $damageChecklistJson = null)
    {
        $output = array();
        $recNoEsc = $conn->real_escape_string(trim((string)$recNo));
        if ($recNoEsc !== '') {
            $sql = "SELECT ct.*, mc.heading, d.check_point AS master_check_point
                    FROM checklist_transaction ct
                    LEFT JOIN mst_chlist_dtl d ON CAST(ct.chk_id AS UNSIGNED) = d.id
                    LEFT JOIN master_checklist mc ON d.chklist_id = mc.id
                    WHERE ct.trans_id = '".$recNoEsc."'
                    AND ct.correction = 'DamageChecklist'
                    ORDER BY mc.id ASC, d.id ASC";
            $result = $conn->query($sql);
            if ($result && $result->num_rows > 0) {
                while ($row = $result->fetch_assoc()) {
                    if (empty($row['params']) && !empty($row['master_check_point'])) {
                        $row['params'] = $row['master_check_point'];
                    }
                    $output[] = $row;
                }
                return $output;
            }
        }

        $details = is_string($receivingDetailsJson) ? json_decode($receivingDetailsJson, true) : $receivingDetailsJson;
        if (is_array($details) && !empty($details['damage_checklist_answers']) && is_array($details['damage_checklist_answers'])) {
            $fromDetails = normalizeStoredDamageChecklistItems($details['damage_checklist_answers'], $recNo);
            if (count($fromDetails) > 0) {
                return $fromDetails;
            }
        }

        $storedChecklist = is_string($damageChecklistJson) ? json_decode($damageChecklistJson, true) : $damageChecklistJson;
        $fromColumn = normalizeStoredDamageChecklistItems($storedChecklist, $recNo);
        if (count($fromColumn) > 0) {
            return $fromColumn;
        }

        return $output;
    }

    function generalMaterialTypeWhere($conn, $materialType)
    {
        $mt = trim((string)$materialType);
        if ($mt === '') {
            return '1=1';
        }
        $types = array($mt);
        if (strcasecmp($mt, 'QC Materials') === 0) {
            $types[] = 'QC Material';
        } elseif (strcasecmp($mt, 'QC Material') === 0) {
            $types[] = 'QC Materials';
        } elseif (strcasecmp($mt, 'IT Materials') === 0) {
            $types[] = 'IT Material';
        } elseif (strcasecmp($mt, 'IT Material') === 0) {
            $types[] = 'IT Materials';
        }
        $in = array();
        foreach (array_unique($types) as $t) {
            $in[] = "'".$conn->real_escape_string($t)."'";
        }
        return "COALESCE(m.material_type, om.material_type, IF(ch.chemical_no IS NOT NULL, 'QC Materials', NULL)) IN (".implode(',', $in).")";
    }

    function fetchReceivingBatchesForChecking($conn, $materialCode, $challanNo, $plantId, $chNo = '')
    {
        $output = array();
        $materialCodeEsc = $conn->real_escape_string($materialCode);
        $challanNoEsc = $conn->real_escape_string($challanNo);
        $plantIdEsc = $conn->real_escape_string($plantId ?? '');
        $chNoEsc = $conn->real_escape_string($chNo ?? '');

        $queries = array(
            "SELECT * FROM sampling_batches
                WHERE material_code = '".$materialCodeEsc."'
                AND challan_no = '".$challanNoEsc."'
                AND (plant_id = '".$plantIdEsc."' OR IFNULL(plant_id,'') = '')
                ORDER BY id ASC",
            "SELECT * FROM sampling_batches
                WHERE material_code = '".$materialCodeEsc."'
                AND challan_no = '".$challanNoEsc."'
                ORDER BY id ASC",
        );
        if ($chNoEsc !== '' && $chNoEsc !== $challanNoEsc) {
            $queries[] = "SELECT * FROM sampling_batches
                WHERE material_code = '".$materialCodeEsc."'
                AND (ch_no = '".$chNoEsc."' OR challan_no = '".$chNoEsc."')
                ORDER BY id ASC";
        }

        $seen = array();
        foreach ($queries as $sql) {
            $result = @$conn->query($sql);
            if ($result && $result->num_rows > 0) {
                while ($row = $result->fetch_assoc()) {
                    $batchNo = trim((string)($row['batch_no'] ?? ''));
                    if ($batchNo === '' || $batchNo === '#Autogenerated') {
                        continue;
                    }
                    $key = $batchNo.'|'.($row['challan_no'] ?? '').'|'.($row['id'] ?? '');
                    if (!isset($seen[$key])) {
                        $seen[$key] = true;
                        $output[] = $row;
                    }
                }
                if (count($output) > 0) {
                    return $output;
                }
            }
        }

        return $output;
    }

    function fetchLabelingBatchesForMaterial($conn, $plantId, $materialCode = '', $materialName = '')
    {
        $output = array();
        $plantEsc = $conn->real_escape_string((string)$plantId);
        $materialCode = trim((string)$materialCode);
        $materialName = trim((string)$materialName);
        $matchParts = array();
        if ($materialCode !== '') {
            $matchParts[] = "c.material_code = '".$conn->real_escape_string($materialCode)."'";
        }
        if ($materialName !== '') {
            $nameEsc = $conn->real_escape_string($materialName);
            $matchParts[] = "LOWER(TRIM(COALESCE(m.material_name, om.material_name, ch.chemical_name,''))) = LOWER('".$nameEsc."')";
            $matchParts[] = "LOWER(TRIM(COALESCE(m.material_name, om.material_name, ch.chemical_name,''))) LIKE CONCAT('%', LOWER('".$nameEsc."'), '%')";
        }
        if (count($matchParts) === 0) {
            return $output;
        }

        $sql = "SELECT c.material_code, c.challan_no, c1.ch_no,
                COALESCE(m.material_name, om.material_name, ch.chemical_name) AS material_name
            FROM challan_materials c
            LEFT JOIN challan c1 ON c.challan_no = c1.challan_no
            LEFT JOIN my_view m ON c.material_code = m.material_code
            LEFT JOIN others_material om ON c.material_code = om.material_code
            LEFT JOIN chemical ch ON c.material_code = ch.chemical_no
            WHERE c1.plant_id = '".$plantEsc."'
            AND c.status != 'pending'
            AND c.receiving = 'approve'
            AND (".implode(' OR ', $matchParts).")
            ORDER BY c1.id DESC";

        $seen = array();
        $result = @$conn->query($sql);
        if ($result && $result->num_rows > 0) {
            while ($row = $result->fetch_assoc()) {
                $batches = fetchReceivingBatchesForChecking(
                    $conn,
                    $row['material_code'] ?? '',
                    $row['challan_no'] ?? '',
                    $plantId,
                    $row['ch_no'] ?? ''
                );
                foreach ($batches as $batch) {
                    $batchNo = trim((string)($batch['batch_no'] ?? ''));
                    if ($batchNo === '') {
                        continue;
                    }
                    $key = $batchNo.'|'.($batch['challan_no'] ?? '');
                    if (isset($seen[$key])) {
                        continue;
                    }
                    $seen[$key] = true;
                    $batch['material_code'] = $row['material_code'] ?? ($batch['material_code'] ?? '');
                    $batch['material_name'] = $row['material_name'] ?? '';
                    $output[] = $batch;
                }
            }
        }
        return $output;
    }

    function normalizeInprocessReceivingRow($conn, &$row, $plantId)
    {
        if (!empty($row['receiving_details']) && is_string($row['receiving_details'])) {
            $decoded = json_decode($row['receiving_details'], true);
            $row['receiving_details'] = is_array($decoded) ? $decoded : $row['receiving_details'];
        }
        $row['batches'] = fetchReceivingBatchesForChecking(
            $conn,
            $row['material_code'] ?? '',
            $row['challan_no'] ?? '',
            $plantId
        );
    }

    function resolveDamageBatchNoFromRow($row)
    {
        $batchNo = trim((string)($row['batch_no'] ?? ''));
        if ($batchNo !== '') {
            return $batchNo;
        }

        $details = $row['receiving_details'] ?? array();
        if (is_string($details)) {
            $decoded = json_decode($details, true);
            $details = is_array($decoded) ? $decoded : array();
        }
        if (!is_array($details)) {
            $details = array();
        }

        $fromDetails = trim((string)($details['damage_batch_no'] ?? $details['batch_no'] ?? ''));
        return $fromDetails;
    }

    function fetchDamageBatchForIpqa($conn, $row)
    {
        $batchNo = resolveDamageBatchNoFromRow($row);
        $materialCodeEsc = $conn->real_escape_string($row['material_code'] ?? '');
        $challanNoEsc = $conn->real_escape_string($row['challan_no'] ?? '');
        $plantIdEsc = $conn->real_escape_string($row['plant_id'] ?? ($_GET['plant_id'] ?? ''));

        if ($batchNo !== '') {
            $batchNoEsc = $conn->real_escape_string($batchNo);
            $sql = "SELECT *, id AS batch_id FROM sampling_batches
                    WHERE batch_no = '".$batchNoEsc."'
                    AND challan_no = '".$challanNoEsc."'
                    ORDER BY id ASC LIMIT 1";
        } else {
            $sql = "SELECT *, id AS batch_id FROM sampling_batches
                    WHERE material_code = '".$materialCodeEsc."'
                    AND challan_no = '".$challanNoEsc."'
                    AND (plant_id = '".$plantIdEsc."' OR IFNULL(plant_id,'') = '')
                    ORDER BY id ASC LIMIT 1";
        }

        $result = $conn->query($sql);
        if ($result && $result->num_rows > 0) {
            return $result->fetch_assoc();
        }

        $sql2 = "SELECT *, id AS batch_id FROM sampling_batches
                WHERE material_code = '".$materialCodeEsc."'
                AND challan_no = '".$challanNoEsc."'
                ORDER BY id ASC LIMIT 1";
        $result2 = $conn->query($sql2);
        if ($result2 && $result2->num_rows > 0) {
            return $result2->fetch_assoc();
        }

        return array();
    }

    function getReceivingActivityMeta($action)
    {
        $action = (string)$action;
        $module = "Receiving";
        $form = "Receiving";
        $nature = "View";

        if ($action == "receiveMaterial") {
            $form = "Awaiting Materials";
            $nature = "Create / Submit";
        } else if ($action == "reject_receiveMaterial") {
            $form = "Awaiting Materials";
            $nature = "Reject";
        } else if ($action == "checkReceivedMaterial") {
            $form = "Material Checking";
            $nature = "Verification / Approval";
        } else if ($action == "getPendingReceivings") {
            $form = "Awaiting Materials";
        } else if ($action == "getInprocessReceivings") {
            $form = "Material Checking";
        } else if ($action == "getReceivingLog" || $action == "getReceivingMaterialLog") {
            $form = "Log Book";
        } else if ($action == "getReceivingLogRejected") {
            $form = "Rejected Materials";
        } else if ($action == "receivingMaterialPDF" || $action == "receivingMaterialLogPDF") {
            $form = "Receiving Reports";
            $nature = "Print / Download";
        } else if ($action == "getCheckPointByForm" || $action == "getReceivingChecklist" || strpos(strtolower($action), "checklist") !== false) {
            $form = "Checklist";
        } else if (strpos(strtolower($action), "receiving") !== false) {
            $form = "Receiving";
        }

        return array("module" => $module, "form" => $form, "nature" => $nature);
    }

