    function formatDurationText($seconds)
    {
        $seconds = intval($seconds);
        if ($seconds <= 0) {
            return "-";
        }
        $h = floor($seconds / 3600);
        $m = floor(($seconds % 3600) / 60);
        $s = $seconds % 60;
        return sprintf("%02d:%02d:%02d", $h, $m, $s);
    }

