                    $row['vendor_name'] = $row['hdr_vendor_name'];
                }
                if (!empty($row['mat_type'])) {
                    $row['material_type'] = $row['mat_type'];
                }
                if (!empty($row['mat_subtype'])) {
                    $row['material_subtype'] = $row['mat_subtype'];
