                OR IFNULL(m.material_type, '') IN ('Raw Material', 'Packing Material')
                OR IFNULL(mv.material_type, '') IN ('Raw Material', 'Packing Material')
            )
            AND LOWER(IFNULL(c.status, 'pending')) NOT IN ('inprocess', 'approve', 'approved', 'rejected')
            AND LOWER(IFNULL(c.receiving, 'pending')) NOT IN ('inprocess', 'approve', 'approved', 'rejected', 'hold')
            ORDER BY c.id DESC
            LIMIT 500";

            $sqlPendingStatus = "SELECT ".$selectCols."
            FROM challan_materials c
            LEFT JOIN challan c1 ON ".$challanJoin."
            ".$materialJoins."
            WHERE (IFNULL(c.plant_id, '') = '".$plantId."' OR IFNULL(c1.plant_id, '') = '".$plantId."')
            AND IFNULL(c.receiving_no, '') = ''
            AND LOWER(IFNULL(c.status, 'pending')) IN ('pending', '')
            AND LOWER(IFNULL(c.receiving, 'pending')) IN ('pending', '')
            AND (
                IFNULL(c1.material_type, '') IN ('Raw Material', 'Packing Material')
                OR IFNULL(m.material_type, '') IN ('Raw Material', 'Packing Material')
                OR IFNULL(mv.material_type, '') IN ('Raw Material', 'Packing Material')
            )
            ORDER BY c.id DESC
            LIMIT 500";

            $sqlOriginal = "SELECT c.*, c1.id AS challan_id, c1.challan_date, c1.po_no, c1.po_date, v.vendor_name,
                m.material_type, m.material_subtype, m.material_name, IFNULL(m.leverages, 0) AS leverages, m.grade
            FROM challan_materials c
            LEFT JOIN challan c1 ON c.challan_no = c1.challan_no
            LEFT JOIN material m ON c.material_code = m.material_code
            LEFT JOIN vendor v ON c.vendor_no = v.vendor_no
            WHERE c.status = 'pending'
            AND c.plant_id = '".$plantId."'
            AND (m.material_type = 'Raw Material' OR m.material_type = 'Packing Material')
            ORDER BY c.id DESC
            LIMIT 500";

            $seenIds = array();
            foreach (array($sqlSecurityFlow, $sqlPendingStatus, $sqlOriginal) as $sql) {
                $result = @$conn->query($sql);
                if ($result === false) {
                    continue;
                }
                while ($row = $result->fetch_assoc()) {
                    $rowId = isset($row['id']) ? $row['id'] : '';
                    if ($rowId !== '' && isset($seenIds[$rowId])) {
                        continue;
                    }
                    if ($rowId !== '') {
                        $seenIds[$rowId] = true;
                    }
                    $normalized = $normalizePendingRow($row);
