            $sql = "SELECT c.id, c.challan_no, c.ch_no, c.material_code, c.qty, c.unit, c.challan_qty,
                    c.received_qty, c.containers, c.grn_no, c.receiving_no, c.receiving, c.receiving_date,
                    c.status, c.po_status, c.vendor_no, c.vendor_type, c.manufacturer_no,
                    c1.id AS challan_id, c1.challan_date, c1.po_date AS challan_header_po_date,
                    po.po_no, po.entry_date AS po_date, po.id AS poId, po.status AS po_order_status,
                    pm.isMatIn,
                    v.vendor_name, v.vendor_no,
                    v2.vendor_name AS manufacturer_name,
                    COALESCE(m.material_name, mv.material_name) AS material_name,
                    COALESCE(m.grade, mv.grade) AS grade,
                    COALESCE(m.material_subtype, mv.material_subtype) AS material_subtype,
                    COALESCE(m.material_type, mv.material_type) AS material_type
                FROM po_material pm
                INNER JOIN purchaseorder po ON po.id = pm.po_no AND po.plant_id = pm.plant_id
                INNER JOIN challan c1 ON (c1.po_no = po.po_no OR c1.po_no = CAST(po.id AS CHAR))
                INNER JOIN challan_materials c ON c.challan_no = c1.challan_no AND c.material_code = pm.material_code
                LEFT JOIN material m ON pm.material_code = m.material_code
                LEFT JOIN my_view mv ON pm.material_code = mv.material_code AND mv.plant_id = pm.plant_id
                LEFT JOIN vendor v ON po.vendor_no = v.vendor_no
                LEFT JOIN vendor v2 ON c.manufacturer_no = v2.vendor_no
                WHERE pm.plant_id = '".$plantId."'
                ".$materialFilter."
                ORDER BY COALESCE(c.receiving_date, c1.challan_date, po.entry_date) DESC, pm.id DESC";

            $result = $conn->query($sql);
            if ($result && $result->num_rows > 0) {
                while ($row = $result->fetch_assoc()) {
