                        $idPart = preg_replace('/[^0-9,]/', '', $gradeRaw);
                        if ($idPart !== '' && preg_match('/^\d+(,\d+)*$/', $idPart)) {
                            $resQ = $conn->query("SELECT GROUP_CONCAT(grade) AS gradeName FROM grade WHERE id IN (".$idPart.")");
                            if ($resQ && ($g = $resQ->fetch_assoc()) && !empty($g['gradeName'])) {
