        else if ($_GET["type"] == "getReceivingLog") {  
            $output = Array();
            
            $sql = "SELECT c.*, c1.id as challan_id,c1.ch_no, c1.challan_date,c1.container_subtype	,c1.container_type	, c1.po_no,c1.po_date, v.vendor_name,v2.vendor_name as manufacturer_name,
            m.material_type, m.material_subtype,m.material_name, m.grade,c1.challan_file,
            c.received_by as entry_user_id,
            TRIM(CONCAT(COALESCE(e_recv.firstname,''), ' ', COALESCE(e_recv.lastname,''))) as entry_by_name,
            e_recv.department as entry_department,
            c1.approve_by as checked_user_id,
            c1.approve_by as checked_by,
            TRIM(CONCAT(COALESCE(e_chk.firstname,''), ' ', COALESCE(e_chk.lastname,''))) as checked_by_name,
            e_chk.department as checked_department,
            c1.approve_date as checked_date_time
            FROM challan_materials c LEFT JOIN challan c1 ON c.challan_no=c1.challan_no LEFT JOIN material m 
            ON c.material_code=m.material_code LEFT JOIN vendor v ON c1.vendor_no=v.vendor_no LEFT JOIN vendor v2 ON c.manufacturer_no=v2.vendor_no
            LEFT JOIN employee e_recv ON c.received_by = e_recv.emp_id
            LEFT JOIN employee e_chk ON c1.approve_by = e_chk.emp_id
            WHERE c1.plant_id= '".$_GET["plant_id"]."' AND c.status !='pending' AND c.receiving ='approve' AND m.material_type = '".$_GET["material_type"]."'
            ORDER BY c1.id DESC";

            $result = $conn->query($sql);
