                $row["receiving_details"] = json_decode($row["receiving_details"]);
                if (!empty($row["damageChecklist"])) {
                    $decodedDamageChecklist = json_decode($row["damageChecklist"], true);
                    $row["damageChecklist"] = is_array($decodedDamageChecklist) ? $decodedDamageChecklist : $row["damageChecklist"];
                }
                if (!empty($row["damage_details"])) {
                    $decodedDamageDetails = json_decode($row["damage_details"], true);
                    $row["damage_details"] = is_array($decodedDamageDetails) ? $decodedDamageDetails : $row["damage_details"];
                }
                
                    
                    $output1 = array();
                    $sql1 = "SELECT * FROM sampling_batches WHERE material_code = '".$row["material_code"]."' AND challan_no = '".$row["challan_no"]."' AND plant_id = '".$_GET['plant_id']."'";
                    
