        else if ($_GET["type"] == "printReceivingMaterialLabel") {
            if (!isset($_GET['id']) || trim($_GET['id']) === '') {
                echo 'Invalid id';
                exit;
            }

            $cmId = $conn->real_escape_string(trim($_GET['id']));
            $batchFilter = '';
            if (isset($_GET['batch_id']) && trim($_GET['batch_id']) !== '') {
                $batchFilter = " AND s.id = '".$conn->real_escape_string(trim($_GET['batch_id']))."'";
            }

            $sql = "SELECT c.*, c1.ch_no, c1.po_no, c1.plant_id, v.vendor_name, v2.vendor_name AS manufacturer_name,
                m.material_name, m.grade, m.material_code,
                TRIM(CONCAT(COALESCE(e.firstname,''), ' ', COALESCE(e.lastname,''))) AS received_by_name,
                p.plant_full_name
                FROM challan_materials c
                LEFT JOIN challan c1 ON c.challan_no = c1.challan_no
                LEFT JOIN material m ON c.material_code = m.material_code
                LEFT JOIN vendor v ON c1.vendor_no = v.vendor_no
                LEFT JOIN vendor v2 ON c.manufacturer_no = v2.vendor_no
                LEFT JOIN employee e ON c.received_by = e.emp_id
                LEFT JOIN plant p ON c1.plant_id = p.plant_id
                WHERE c.id = '".$cmId."' LIMIT 1";

            $result = $conn->query($sql);
            if (!$result || $result->num_rows === 0) {
                echo 'Invalid id';
                exit;
            }

            $cm = $result->fetch_assoc();
            $plantName = 'MEDICAP LABORATORIES';
            if (!empty(trim($cm['plant_full_name']))) {
                $plantName = strtoupper(trim($cm['plant_full_name']));
            }
            $productDesc = trim($cm['material_name']);
            if (!empty($cm['grade'])) {
                $productDesc .= ' / ' . $cm['grade'];
            }
            $manufacturer = trim($cm['manufacturer_name']);
            if ($manufacturer === '' && !empty($cm['manufacturer'])) {
                $manufacturer = $cm['manufacturer'];
            }
            $supplier = trim($cm['vendor_name']);
            $receivedBy = trim($cm['received_by_name']);
            if ($receivedBy === '') {
                $receivedBy = $cm['received_by'];
            }
            $receivedDate = !empty($cm['receiving_date']) ? date('d-m-Y', strtotime($cm['receiving_date'])) : '';

            $batchSql = "SELECT s.* FROM sampling_batches s
                WHERE s.material_code = '".$conn->real_escape_string($cm['material_code'])."'
                AND s.challan_no = '".$conn->real_escape_string($cm['challan_no'])."'
                AND s.plant_id = '".$conn->real_escape_string($_GET['plant_id'])."'".$batchFilter."
                ORDER BY s.id ASC";
            $batchResult = $conn->query($batchSql);
            $batches = array();
            if ($batchResult && $batchResult->num_rows > 0) {
                while ($batchRow = $batchResult->fetch_assoc()) {
                    $batches[] = $batchRow;
                }
            }
            if (count($batches) === 0) {
                $batches[] = array(
                    'supplier_batch_no' => '',
                    'batch_no' => '',
                    'exp_date' => '',
                    'qty_received' => $cm['received_qty'],
                    'unit' => $cm['unit'],
                    'total_containers' => max(1, (int)$cm['containers']),
                );
            }

            $pdf = new TCPDF('P', 'mm', 'A4');
            $pdf->SetCreator(PDF_CREATOR);
            $pdf->SetAuthor('Medicap Laboratories');
            $pdf->SetTitle('Receiving & Quarantine Material Labels');
            $pdf->setPrintHeader(false);
            $pdf->setPrintFooter(false);
            $pdf->SetMargins(10, 10, 10);
            $pdf->SetAutoPageBreak(true, 10);
            $pdf->SetFont('helvetica', '', 8);

            $labelItems = array();
            foreach ($batches as $batch) {
                $mfgLot = trim($batch['supplier_batch_no']);
                if ($mfgLot === '') {
                    $mfgLot = $batch['batch_no'];
                }
                $lotNo = $batch['batch_no'];
                $expDate = !empty($batch['exp_date']) ? date('d-m-Y', strtotime($batch['exp_date'])) : '';
                $totalQty = trim($batch['qty_received'] . ' ' . $batch['unit']);
                $count = max(1, (int)$batch['total_containers']);

                for ($i = 1; $i <= $count; $i++) {
                    $labelItems[] = array(
                        'plantName' => $plantName,
                        'productDesc' => $productDesc,
                        'mfgLot' => $mfgLot,
                        'manufacturer' => $manufacturer,
                        'supplier' => $supplier,
                        'materialCode' => $cm['material_code'],
                        'lotNo' => $lotNo,
                        'expDate' => $expDate,
                        'containerNo' => $i,
                        'containerTotal' => $count,
                        'receivedBy' => $receivedBy,
                        'receivedDate' => $receivedDate,
                        'totalQty' => $totalQty,
                    );
                }
            }

            if (count($labelItems) === 0) {
                echo 'No labels to print';
                exit;
            }

            $html = '';
            foreach ($labelItems as $index => $item) {
                if ($index > 0) {
                    $html .= '<br pagebreak="true"/>';
                }
                $html .= buildQuarantineReceivingLabelSheet($item);
            }

            $pdf->AddPage();
            $pdf->writeHTML($html, true, false, false, false, '');
            $pdf->Output('Quarantine_Receiving_Labels.pdf', 'I');
        }
        else if ($_GET["type"] == "getReceivingMaterialLog") {
            $output = array();
            $plant_id = $conn->real_escape_string($_GET["plant_id"]);
            $material_type = $conn->real_escape_string($_GET["material_type"]);
            $from_date = isset($_GET["from_date"]) ? $conn->real_escape_string($_GET["from_date"]) : "";
            $to_date = isset($_GET["to_date"]) ? $conn->real_escape_string($_GET["to_date"]) : "";

            $dateFilter = "";
            if ($from_date != "" && $to_date != "") {
                $dateFilter = " AND DATE(c.receiving_date) BETWEEN '".$from_date."' AND '".$to_date."' ";
            }

            $sql = "SELECT s.id as batch_id, s.batch_no as lot_number, s.supplier_batch_no, s.qty_received, s.unit,
            c.material_code, c.receiving_no, c.receiving_date, c.received_by, c.challan_no, c.id as challan_material_id,
            m.material_name, m.material_type, m.material_subtype,
            v.vendor_name,
            TRIM(CONCAT(COALESCE(e.firstname,''), ' ', COALESCE(e.lastname,''))) as received_by_name,
            e.firstname, e.lastname
            FROM sampling_batches s
            INNER JOIN challan_materials c ON s.material_code = c.material_code AND s.challan_no = c.challan_no
            INNER JOIN challan c1 ON c.challan_no = c1.challan_no
            LEFT JOIN material m ON c.material_code = m.material_code
            LEFT JOIN vendor v ON c1.vendor_no = v.vendor_no
            LEFT JOIN employee e ON c.received_by = e.emp_id
            WHERE c1.plant_id = '".$plant_id."'
            AND c.status != 'pending'
            AND c.receiving = 'approve'
            AND m.material_type = '".$material_type."'
            ".$dateFilter."
            ORDER BY c.receiving_date DESC, s.id DESC";

            $result = $conn->query($sql);
            if ($result && $result->num_rows > 0) {
                while ($row = $result->fetch_assoc()) {
                    $initials = "";
                    $fn = trim((string)$row["firstname"]);
                    $ln = trim((string)$row["lastname"]);
                    if ($fn != "" && $ln != "") {
                        $initials = strtoupper(substr($fn, 0, 1) . substr($ln, 0, 1));
                    } else if ($fn != "") {
                        $initials = strtoupper(substr($fn, 0, 2));
                    } else {
                        $initials = trim((string)$row["received_by"]);
                    }
                    $row["assigned_by_initials"] = $initials;
                    $row["assigned_by_date"] = $row["receiving_date"];
                    $output[] = $row;
                }
            }
            echo json_encode($output);
