                                $qrSize = 40;  // QR Code size (width & height)
                                $spacing = 20; // Space between QR codes
                                $itemsPerRow = 4; // QR codes per row
                                $counter = 0; // To track QR codes per row
                            
                                $xPos = $xStart;
                                $yPos = $yStart;
                            
                                for ($i = 1; $i <= $total_containers; $i++) {
