                                    $xPos += $qrSize + $spacing;
                                    $counter++;
                            
                                    // If row is full, move to the next line
                                    if ($counter == $itemsPerRow) {
                                        $xPos = $xStart; // Reset X position
                                        $yPos += $qrSize + $spacing; // Move to next row
                                        $counter = 0; // Reset counter
