                LEFT JOIN chemical ch ON c.material_code=ch.chemical_no
                LEFT JOIN vendor v ON c1.vendor_no=v.vendor_no
                LEFT JOIN vendor v2 ON c.manufacturer_no=v2.vendor_no
                LEFT JOIN employee e_recv ON c.received_by = e_recv.emp_id
                LEFT JOIN employee e_chk ON c1.approve_by = e_chk.emp_id
