    }

    // Uses the same fields as getReceivingLogGeneralMaterials (plus optional date filter)
    $sql = "SELECT
                c.*,
                c1.id as challan_id,
                c1.ch_no,
                c1.challan_date,
                c1.container_subtype,
                c1.container_type,
                c1.po_no,
