                <td style="width: 45px;font-size:7px;">'.$receiving_date.'</td>
                <td style="width: 55px;font-size:7px;">'.htmlspecialchars($row['challan_no'] ?? $row['ch_no'] ?? '').'<br>'.$challan_date.'</td>
                <td style="width: 50px;font-size:7px;">'.htmlspecialchars($row['material_code'] ?? '').'</td>
                <td style="width: 80px;font-size:7px;">'.htmlspecialchars($row['material_name'] ?? '').'</td>
                <td style="width: 55px;font-size:7px;">'.htmlspecialchars($container).'</td>
                <td style="width: 70px;font-size:7px;">'.htmlspecialchars($row['vendor_name'] ?? '').'</td>
                <td style="width: 35px;font-size:7px;">'.htmlspecialchars($row['received_qty'] ?? '').'</td>
                <td style="width: 55px;font-size:7px;">'.htmlspecialchars($row['po_no'] ?? '').'<br>'.$po_date.'</td>
                <td style="width: 71px;font-size:7px;white-space:pre-line;">'.htmlspecialchars($entryChecked).'</td>
            </tr>';
        }
    } else {
        $html .= '<tr><td colspan="10" style="text-align:center;font-size:9px;">No data found for selected filters.</td></tr>';
    }

    $html .= '</tbody></table>';

    $pdf->writeHTML($html, true, false, false, false, '');
    $pdf->Output('', 'I');
    }
                
            else {// Medicap / default plant — same data as getReceivingMaterialLog UI
                    $_GET['filename'] = 'Receiving of Material Log';
                    $_GET['pdftype'] = 'onlyheader';
                    $_GET['pdfpage'] = 'L';
                    $_GET['pdfleft'] = 5;
                    $_GET['pdfright'] = 5;
                    $_GET['pdfy'] = 26;
                    include('../pdfimp2.php');

            $plant_id = $conn->real_escape_string(isset($_GET["plant_id"]) ? $_GET["plant_id"] : "");
            $material_type = trim(isset($_GET["material_type"]) ? $_GET["material_type"] : 'Raw Material');
            if ($material_type === '') {
                $material_type = 'Raw Material';
            }
            $material_type_esc = $conn->real_escape_string($material_type);
            $from_date = isset($_GET["from_date"]) ? trim($_GET["from_date"]) : "";
            $to_date = isset($_GET["to_date"]) ? trim($_GET["to_date"]) : "";

            $dateFilter = "";
            if ($from_date !== "" && $to_date !== "") {
                $from_esc = $conn->real_escape_string($from_date);
                $to_esc = $conn->real_escape_string($to_date);
                $dateFilter = " AND DATE(c.receiving_date) BETWEEN '".$from_esc."' AND '".$to_esc."' ";
            }

            $tableWidth = '287mm';
            $metaTable = '<table style="width:'.$tableWidth.'; border-collapse:collapse; font-family:dejavusans;" cellpadding="2" border="1">
            <tr>
        <td style="width:18%; padding:3px 4px; font-size:8px;">Format Title :</td>
        <td style="width:82%; padding:3px 4px; font-size:8px;">Raw Material Inward Register</td>
        </tr>
        <tr>
        <td style="width:18%; padding:3px 4px; font-size:8px;">Format No.:</td>
        <td style="width:32%; padding:3px 4px; font-size:8px;">F/SOP/WR/002/03-01</td>
        <td style="width:18%; padding:3px 4px; font-size:8px;">Page No.:</td>
        <td style="width:32%; padding:3px 4px; font-size:8px;">1 of 1</td>
        </tr>
        <tr>
        <td style="width:18%; padding:3px 4px; font-size:8px;">Ref. SOP No.:</td>
        <td style="width:82%; padding:3px 4px; font-size:8px;">SOP/WR/002</td>
        </tr>
        </table>';

            $html .= $metaTable.'
            <h2 style="text-align:center; font-size:13px; margin:6px 0 4px 0;">Receiving of Material Log</h2>
            <div style="font-size:9px; margin-bottom:4px;">
                <strong>Material Type:</strong> '.htmlspecialchars($material_type);
            if ($from_date !== "" && $to_date !== "") {
                $html .= ' &nbsp;&nbsp; <strong>From:</strong> '.htmlspecialchars($from_date).
                         ' &nbsp;&nbsp; <strong>To:</strong> '.htmlspecialchars($to_date);
            }
            $html .= '</div>
            <table style="width:'.$tableWidth.'; border-collapse:collapse; font-family:dejavusans;" cellpadding="2" border="1">
                    <tr style="text-align:center; background-color:#DDDAD9; font-weight:bold;">
                        <td style="width:4%; font-size:8px;">Sr.<br/>No.</td>
                        <td style="width:10%; font-size:8px;">Lot<br/>Number</td>
                        <td style="width:9%; font-size:8px;">Code<br/>Number</td>
                        <td style="width:22%; font-size:8px;">Name of Material /<br/>Description</td>
                        <td style="width:8%; font-size:8px;">Quantity</td>
                        <td style="width:9%; font-size:8px;">Receiving<br/>Number</td>
                        <td style="width:18%; font-size:8px;">Supplier<br/>Name</td>
                        <td style="width:9%; font-size:8px;">Supplier<br/>Lot No.</td>
                        <td style="width:11%; font-size:8px;">Assigned By<br/>(Initial / Date)</td>
                    </tr><tbody>';

            $sql = "SELECT s.id as batch_id, s.batch_no as lot_number, s.supplier_batch_no, s.qty_received, s.unit,
            c.material_code, c.receiving_no, c.receiving_date, c.received_by,
            m.material_name, m.material_type,
            v.vendor_name,
            TRIM(CONCAT(COALESCE(e.firstname,''), ' ', COALESCE(e.lastname,''))) as received_by_name,
            e.firstname, e.lastname
            FROM sampling_batches s
            INNER JOIN challan_materials c ON s.material_code = c.material_code AND s.challan_no = c.challan_no
            INNER JOIN challan c1 ON c.challan_no = c1.challan_no
            LEFT JOIN material m ON c.material_code = m.material_code
            LEFT JOIN vendor v ON c1.vendor_no = v.vendor_no
            LEFT JOIN employee e ON c.received_by = e.emp_id
            WHERE c1.plant_id = '".$plant_id."'
            AND c.status != 'pending'
            AND c.receiving = 'approve'
            AND m.material_type = '".$material_type_esc."'
            ".$dateFilter."
            ORDER BY c.receiving_date DESC, s.id DESC";

            $result = $conn->query($sql);
            if ($result === false) {
                $html .= '<tr><td colspan="9" style="font-size:8px;color:red;">SQL Error: '.htmlspecialchars($conn->error).'</td></tr>';
            } else if ($result->num_rows > 0) {
                $counter = 1;
                while ($row = $result->fetch_assoc()) {
                    $lot = trim((string)(isset($row['lot_number']) ? $row['lot_number'] : ''));
                    if ($lot === '') {
                        $lot = '-';
                    }

                    $qty = isset($row['qty_received']) ? trim((string)$row['qty_received']) : '';
                    $unit = isset($row['unit']) ? trim((string)$row['unit']) : '';
                    $qtyDisplay = ($qty === '') ? '-' : ($unit !== '' ? $qty.' '.$unit : $qty);

                    $recvRaw = isset($row['receiving_no']) ? trim((string)$row['receiving_no']) : '';
                    $recvDisplay = '-';
                    if ($recvRaw !== '') {
                        $parts = explode('/', $recvRaw);
                        $lastPart = count($parts) ? $parts[count($parts) - 1] : $recvRaw;
                        $num = preg_replace('/\D/', '', $lastPart);
                        if ($num !== '') {
                            $recvDisplay = str_pad($num, 6, '0', STR_PAD_LEFT);
                        } else {
                            $allDigits = preg_replace('/\D/', '', $recvRaw);
                            $recvDisplay = $allDigits !== '' ? str_pad(substr($allDigits, -6), 6, '0', STR_PAD_LEFT) : $recvRaw;
                        }
                    }

                    $fn = trim((string)(isset($row['firstname']) ? $row['firstname'] : ''));
                    $ln = trim((string)(isset($row['lastname']) ? $row['lastname'] : ''));
                    if ($fn !== '' && $ln !== '') {
                        $initials = strtoupper(substr($fn, 0, 1).substr($ln, 0, 1));
                    } else if ($fn !== '') {
                        $initials = strtoupper(substr($fn, 0, 2));
                    } else {
                        $initials = trim((string)(isset($row['received_by']) ? $row['received_by'] : ''));
                    }
                    if ($initials === '') {
                        $initials = '-';
                    }

                    $recvDate = '';
                    if (!empty($row['receiving_date']) && strtotime($row['receiving_date'])) {
                        $recvDate = date('d-m-Y', strtotime($row['receiving_date']));
                    }
                    $assignedBy = $initials.($recvDate !== '' ? ' / '.$recvDate : '');

                    $html .= '<tr nobr="true">
                    <td style="width:4%; font-size:8px; text-align:center; padding:3px 2px;">'.$counter++.'</td>
                    <td style="width:10%; font-size:8px; text-align:center; padding:3px 2px;">'.htmlspecialchars($lot).'</td>
                    <td style="width:9%; font-size:8px; text-align:center; padding:3px 2px;">'.htmlspecialchars($row['material_code'] ?? '').'</td>
                    <td style="width:22%; font-size:8px; text-align:left; padding:3px 2px;">'.htmlspecialchars($row['material_name'] ?? '').'</td>
                    <td style="width:8%; font-size:8px; text-align:center; padding:3px 2px;">'.htmlspecialchars($qtyDisplay).'</td>
                    <td style="width:9%; font-size:8px; text-align:center; padding:3px 2px;">'.htmlspecialchars($recvDisplay).'</td>
                    <td style="width:18%; font-size:8px; text-align:left; padding:3px 2px;">'.htmlspecialchars($row['vendor_name'] ?? '').'</td>
                    <td style="width:9%; font-size:8px; text-align:center; padding:3px 2px;">'.htmlspecialchars($row['supplier_batch_no'] ?? '-').'</td>
                    <td style="width:11%; font-size:8px; text-align:center; padding:3px 2px;">'.htmlspecialchars($assignedBy).'</td>
                        </tr>';
                }
            } else {
                $html .= '<tr><td colspan="9" style="text-align:center;font-size:8px;">No records found for selected filters.</td></tr>';
            }

                $html.='</tbody></table>';

            $pdf->writeHTML($html, true, false, false, false, '');
            $pdf->Output('','I');

            }	
        }  
        
        
